CREATE TEMP TABLE sibling_before AS SELECT to_jsonb(m) AS value FROM public.organization_memberships m WHERE organization_id='a2000000-0000-4000-8000-000000000102';
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','a2000000-0000-4000-8000-000000000005',true);
SELECT set_config('request.jwt.claims','{"sub":"a2000000-0000-4000-8000-000000000005","email":"invite5@example.test"}',true);
SELECT is((SELECT accept_status FROM public.accept_organization_invitation('a2000000-0000-4000-8000-000000000301')),'not_found','wrong email cannot accept');
SELECT is((SELECT decline_status FROM public.decline_organization_invitation('a2000000-0000-4000-8000-000000000301')),'not_found','wrong email cannot decline');
SELECT is((SELECT revoke_status FROM public.revoke_organization_invitation('a2000000-0000-4000-8000-000000000301','a2000000-0000-4000-8000-000000000101')),'not_found','ordinary member cannot revoke');
RESET ROLE;
SET LOCAL ROLE anon;
SELECT set_config('request.jwt.claim.sub','',true);
SELECT set_config('request.jwt.claims','{}',true);
SELECT is((SELECT accept_status FROM public.accept_organization_invitation('a2000000-0000-4000-8000-000000000301')),'not_found','anonymous accept denied');
SELECT is((SELECT decline_status FROM public.decline_organization_invitation('a2000000-0000-4000-8000-000000000301')),'not_found','anonymous decline denied');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','a2000000-0000-4000-8000-000000000001',true);
SELECT set_config('request.jwt.claims','{"sub":"a2000000-0000-4000-8000-000000000001","email":"invite1@example.test"}',true);
SELECT is((SELECT revoke_status FROM public.revoke_organization_invitation('a2000000-0000-4000-8000-000000000307','a2000000-0000-4000-8000-000000000102')),'not_found','wrong Organization cannot revoke');
RESET ROLE;
SELECT is((SELECT status::text FROM public.organization_invitations WHERE id='a2000000-0000-4000-8000-000000000307'),'pending','denied revocation preserves pending invitation');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','a2000000-0000-4000-8000-000000000001',true);
SELECT set_config('request.jwt.claims','{"sub":"a2000000-0000-4000-8000-000000000001","email":"invite1@example.test"}',true);
SELECT is((SELECT revoke_status FROM public.revoke_organization_invitation('a2000000-0000-4000-8000-000000000307','a2000000-0000-4000-8000-000000000101')),'revoked','owner can revoke in their Organization');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','a2000000-0000-4000-8000-000000000002',true);
SELECT set_config('request.jwt.claims','{"sub":"a2000000-0000-4000-8000-000000000002","email":"invite2@example.test"}',true);
SELECT is((SELECT accept_status FROM public.accept_organization_invitation('a2000000-0000-4000-8000-000000000301')),'accepted','member accepts their own invitation');
SELECT is((SELECT accept_status FROM public.accept_organization_invitation('a2000000-0000-4000-8000-000000000301')),'already_accepted','accept replay preserves history');
SELECT is((SELECT decline_status FROM public.decline_organization_invitation('a2000000-0000-4000-8000-000000000301')),'already_accepted','accepted invitation cannot be declined');
RESET ROLE;
SELECT results_eq($$ SELECT user_id,email,role::text,member_preset,capability_overrides,access_scope_kind,access_scope_group_ids FROM public.organization_memberships WHERE organization_id='a2000000-0000-4000-8000-000000000101' AND user_id='a2000000-0000-4000-8000-000000000002' $$,$$ VALUES ('a2000000-0000-4000-8000-000000000002'::uuid,'invite2@example.test'::text,'member'::text,'viewer'::text,'{"calendar":"operate","personnel":"none"}'::jsonb,'groups'::text,ARRAY['a2000000-0000-4000-8000-000000000201','a2000000-0000-4000-8000-000000000202']::uuid[]) $$,'member identity and multi-Group capability snapshot are persisted');
SELECT ok((SELECT accepted_by='a2000000-0000-4000-8000-000000000002' AND accepted_at IS NOT NULL AND invited_by='a2000000-0000-4000-8000-000000000001' FROM public.organization_invitations WHERE id='a2000000-0000-4000-8000-000000000301'),'accepted history retains inviter and JWT-derived actor');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','a2000000-0000-4000-8000-000000000003',true);
SELECT set_config('request.jwt.claims','{"sub":"a2000000-0000-4000-8000-000000000003","email":"invite3@example.test"}',true);
SELECT is((SELECT accept_status FROM public.accept_organization_invitation('a2000000-0000-4000-8000-000000000302')),'accepted','admin invitation accepted');
RESET ROLE;
SELECT results_eq($$ SELECT role::text,member_preset,capability_overrides,access_scope_kind,access_scope_group_ids FROM public.organization_memberships WHERE organization_id='a2000000-0000-4000-8000-000000000101' AND user_id='a2000000-0000-4000-8000-000000000003' $$,$$ VALUES ('admin'::text,'editor'::text,'{}'::jsonb,'organization'::text,ARRAY[]::uuid[]) $$,'admin acceptance canonicalizes full Organization access');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','a2000000-0000-4000-8000-000000000004',true);
SELECT set_config('request.jwt.claims','{"sub":"a2000000-0000-4000-8000-000000000004","email":"invite4@example.test"}',true);
SELECT is((SELECT decline_status FROM public.decline_organization_invitation('a2000000-0000-4000-8000-000000000303')),'declined','invitee may decline');
SELECT is((SELECT decline_status FROM public.decline_organization_invitation('a2000000-0000-4000-8000-000000000303')),'already_declined','decline replay cannot repeat transition');
SELECT is((SELECT accept_status FROM public.accept_organization_invitation('a2000000-0000-4000-8000-000000000303')),'not_found','declined invitation cannot accept');
SELECT set_config('request.jwt.claim.sub','a2000000-0000-4000-8000-000000000006',true);
SELECT set_config('request.jwt.claims','{"sub":"a2000000-0000-4000-8000-000000000006","email":"invite6@example.test"}',true);
SELECT is((SELECT accept_status FROM public.accept_organization_invitation('a2000000-0000-4000-8000-000000000304')),'expired','exact invitation expiry denies acceptance');
SELECT is((SELECT decline_status FROM public.decline_organization_invitation('a2000000-0000-4000-8000-000000000304')),'expired','expired invitation cannot decline');
RESET ROLE;
SELECT ok((SELECT declined_by='a2000000-0000-4000-8000-000000000004' AND declined_at IS NOT NULL FROM public.organization_invitations WHERE id='a2000000-0000-4000-8000-000000000303'),'decline preserves history and actor');
SELECT is((SELECT count(*)::integer FROM public.organization_memberships WHERE organization_id='a2000000-0000-4000-8000-000000000101' AND user_id='a2000000-0000-4000-8000-000000000004'),0,'decline and expiry grant no membership');
INSERT INTO public.access_requests(id,email,name,status) VALUES ('a2000000-0000-4000-8000-000000000401','invite7@example.test','Rejected','pending');
INSERT INTO public.access_request_organization_invitation_links(access_request_id,organization_invitation_id,organization_id,invited_by,invited_at,intended_membership_role,intended_permissions,intended_access_scope_kind) VALUES ('a2000000-0000-4000-8000-000000000401','a2000000-0000-4000-8000-000000000305','a2000000-0000-4000-8000-000000000101','a2000000-0000-4000-8000-000000000001',now(),'member','{}','organization');
SET LOCAL ROLE service_role;
SELECT is((SELECT reject_status FROM public.reject_access_request_and_block_linked_invitations('a2000000-0000-4000-8000-000000000401','a2000000-0000-4000-8000-000000000001')),'rejected','platform rejection blocks linked pending invitation');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','a2000000-0000-4000-8000-000000000004',true);
SELECT set_config('request.jwt.claims','{"sub":"a2000000-0000-4000-8000-000000000004","email":"invite4@example.test"}',true);
SELECT set_config('request.jwt.claim.sub','a2000000-0000-4000-8000-000000000007',true);
SELECT set_config('request.jwt.claims','{"sub":"a2000000-0000-4000-8000-000000000007","email":"invite7@example.test"}',true);
SELECT is((SELECT accept_status FROM public.accept_organization_invitation('a2000000-0000-4000-8000-000000000305')),'blocked','rejected linked invitation cannot accept');
SELECT is((SELECT decline_status FROM public.decline_organization_invitation('a2000000-0000-4000-8000-000000000305')),'blocked','rejected linked invitation cannot decline');
RESET ROLE;
SELECT ok((SELECT status='blocked' AND blocked_by='a2000000-0000-4000-8000-000000000001' AND blocked_at IS NOT NULL FROM public.organization_invitations WHERE id='a2000000-0000-4000-8000-000000000305'),'blocking retains invitation and reviewer');
SELECT is((SELECT status::text FROM public.organization_invitations WHERE id='a2000000-0000-4000-8000-000000000308'),'pending','rejection leaves independent sibling invitation untouched');
SELECT results_eq($$ SELECT to_jsonb(m) FROM public.organization_memberships m WHERE organization_id='a2000000-0000-4000-8000-000000000102' $$,'SELECT value FROM sibling_before','sibling membership is unchanged');
CREATE FUNCTION pg_temp.reject_invitation_member() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.user_id='a2000000-0000-4000-8000-000000000005' THEN RAISE EXCEPTION 'synthetic membership failure'; END IF; RETURN NEW; END $$;
CREATE TRIGGER reject_invitation_member BEFORE INSERT ON public.organization_memberships FOR EACH ROW EXECUTE FUNCTION pg_temp.reject_invitation_member();
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','a2000000-0000-4000-8000-000000000005',true);
SELECT set_config('request.jwt.claims','{"sub":"a2000000-0000-4000-8000-000000000005","email":"invite5@example.test"}',true);
SELECT throws_ok($$ SELECT * FROM public.accept_organization_invitation('a2000000-0000-4000-8000-000000000306') $$,'P0001','synthetic membership failure','membership write failure propagates');
RESET ROLE;
SELECT ok((SELECT status='pending' AND accepted_at IS NULL AND accepted_by IS NULL FROM public.organization_invitations WHERE id='a2000000-0000-4000-8000-000000000306'),'failed membership write rolls back invitation acceptance');
SELECT is((SELECT count(*)::integer FROM public.organization_memberships WHERE organization_id='a2000000-0000-4000-8000-000000000101' AND user_id='a2000000-0000-4000-8000-000000000005'),0,'failed acceptance leaves no membership');
DROP TRIGGER reject_invitation_member ON public.organization_memberships;
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','a2000000-0000-4000-8000-000000000005',true);
SELECT set_config('request.jwt.claims','{"sub":"a2000000-0000-4000-8000-000000000005","email":"invite5@example.test"}',true);
SELECT is((SELECT accept_status FROM public.accept_organization_invitation('a2000000-0000-4000-8000-000000000306')),'accepted','retry after storage recovery succeeds');
RESET ROLE;
SELECT * FROM finish();
ROLLBACK;
